                                        "type": "string"
                                    }
                                },
                                "required": [
                                    "type",
                                    "status",
                                    "lastTransitionTime",
                                    "reason",
                                    "message"
                                ]
                            }
                        }
                    }
                }
            }
        }

        # Add the default observer schema to the resource
