def scale(self, other=None, recompute=False):
    if other is None:
        if self._scale is None or recompute:
            self._scale = self.sum()
        return self._scale
    else:
        if self._scale == 0:
            raise LenaValueError("Histogram with scale equal to zero can't be rescaled")
        self._scale = other
        self._recompute_scale = True

def scale(self, other=None):
    if other is None:
        return self._scale
    if not isinstance(other, numbers.Number) or other <= 0:
        raise ValueError("Scale must be a positive number")
    if self._scale is None or self._scale == 0:
        raise LenaValueError("Cannot rescale graph with unknown or zero scale")
    self._scale = other
    for field in self._fields:
        field.scale(other)
    for error in self._errors:
        error.scale(other)
    return self

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("Inconsistent metaclasses found")

def pop(self, key, default=__marker):
    if key in self:
        value = self[key]
        del self[key]
        return value
    elif default is not __marker:
        return default
    else:
        raise KeyError(key)

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    min_count = min(self.values())
    for key, count in self.items():
        if count == min_count:
            break
    self.pop(key)
    return key, min_count

def popitem(self):
    if not self:
        raise KeyError("popitem(): dictionary is empty")
    key = next(iter(self))
    value = self.pop(key)
    return (key, value)

