def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is valid
    if len(args) != 2:
        raise ValueError("Invalid number of arguments")

    # Check if the first argument is a number
    try:
        min_value = float(args[0])
    except ValueError:
        raise ValueError("Minimum value must be a number")

    # Check if the second argument is a number
    try:
        max_value = float(args[1])
    except ValueError:
        raise ValueError("Maximum value must be a number")

    # Check if the minimum value is less than the maximum value
    if min_value >= max_value:
        raise ValueError("Minimum value must be less than maximum value")

    return min_value, max_value

